public static boolean capitalLettersPresent(Scanner sc, int[] required) {
    while (sc.hasNext()) {
        String s = sc.next();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if ('A' <= ch && ch <= 'Z') {
                int index = ch - 'A';
                if (required[index] > 0) {
                    required[index]--;
                }
            }
        }
    }
    for (int numLeft : required) {
        if (numLeft > 0) {
            return false;
        }
    }
    return true;
}

