    int numMove = one.length - two.length;
    for (int i = numMove - 1; i >= 0; i--) {
        one[i + two.length] = one[i];
    }
    int limit = two.length;
    if (one.length < two.length) {
        limit = one.length;
    }
    for (int i = 0; i < limit; i++) {
        one[i] = two[i];
    }
}

