public boolean addIfFrequencyLessThan(E tgt, int freq) {
    if (first == null) {
        first = new Node<>(tgt);
        return true;
    }
    Node<E> scout = first;
    Node<E> trailer = first;
    int count = 0;
    while (scout != null) {
        if (scout.data.equals(tgt)) {
            count++;
            if (count == freq) {
                return false;
            }
        }
        trailer = scout;
        scout = scout.next;
    }
    trailer.next = new Node<>(tgt);
    return true;
}

